// Spanish AI — Livro online de espanhol (A1 → C2).
// Conteúdo estruturado em capítulos com teoria, exemplos, léxico,
// exercícios de fixação por tópico e prova final por nível.
//
// As explicações são apresentadas no idioma da interface (PT/EN).
// Os exemplos e palavras-alvo permanecem em ESPANHOL (conteúdo-alvo).

import type { LevelId } from "@/data/games";

export type ExerciseType = "multiple-choice" | "fill-blank" | "translate";

export interface Exercise {
  id: string;
  type: ExerciseType;
  question: string;
  options?: string[];
  answer: string;
  explanation?: string;
  /** Texto em espanhol com botão de ouvir: exercício de escuta ("ouça e escolha") ou frase-modelo. */
  audio?: string;
}

export interface LexiconEntry {
  es: string;
  pt: string;
  example?: string;
  tag?: "profesional" | "coloquial" | "formal" | "expresión";
}

export interface Topic {
  id: string;
  title: string;
  blocks: TopicBlock[];
  exercises: Exercise[];
}

/** Cartão de pronúncia: uma letra, vogal ou som, com nome falado e palavras de exemplo. */
export interface SoundItem {
  /** O que aparece em destaque no cartão (ex.: "B b", "CH", "ce / ci"). */
  label: string;
  /** Nome da letra em espanhol (ex.: "be"), se houver. */
  name?: string;
  /** Texto falado no botão principal; padrão: name, senão o primeiro exemplo. */
  say?: string;
  /** Como soa, explicado em português. */
  description: string;
  /** Palavras em espanhol, cada uma com botão de ouvir. */
  examples: string[];
}

export type TopicBlock =
  | { kind: "paragraph"; text: string }
  | { kind: "heading"; text: string }
  | { kind: "example"; es: string; pt: string }
  /** speak: os itens são só espanhol e ganham botão de ouvir. */
  | { kind: "list"; items: string[]; speak?: boolean }
  /** audioCols: índices das colunas em espanhol (ganham botão de ouvir). */
  | { kind: "table"; headers: string[]; rows: string[][]; audioCols?: number[] }
  | { kind: "tip"; text: string }
  | { kind: "sounds"; items: SoundItem[] };

export interface Chapter {
  id: string;
  number: number;
  title: string;
  summary: string;
  topics: Topic[];
  lexicon: LexiconEntry[];
  /** Perguntas dedicadas do quiz (diferentes dos exercícios). */
  quiz?: Exercise[];
  /** Palavras de vocabulário extra para flashcards (diferentes do léxico). */
  flashcards?: LexiconEntry[];
  /** Resumo curto para a aba Revisão. */
  briefReview?: string;
}

export interface CourseLevel {
  level: LevelId;
  title: string;
  description: string;
  chapters: Chapter[];
  /** Banco rotativo da prova final — preenchido em runtime via exam-banks.ts. */
  examBank?: import("./exam-banks").ExamBank;
}

