      flashcards: [
        { es: "el titular", pt: "a manchete" },
        { es: "la portavoz / el portavoz", pt: "o/a porta-voz" },
        { es: "el comunicado de prensa", pt: "o comunicado à imprensa", tag: "formal" },
        { es: "la rueda de prensa", pt: "a coletiva de imprensa" },
        { es: "el fichaje", pt: "a contratação (esporte)" },
        { es: "la subida", pt: "a alta, o aumento", example: "La subida de la luz preocupa a las familias." },
        { es: "la bajada", pt: "a queda, a baixa" },
        { es: "aseverar", pt: "asseverar, afirmar", tag: "formal" },
        { es: "el aprendizaje", pt: "a aprendizagem" },
        { es: "la madurez", pt: "a maturidade" },
      ],
      quiz: [
        { id: "c1-02-q1", type: "multiple-choice", question: "Sufixo feminino mais comum:", options: ["-miento", "-ción", "-aje"], answer: "-ción", explanation: "-ción/-sión formam substantivos femininos; -miento e -aje são masculinos." },
        { id: "c1-02-q2", type: "multiple-choice", question: "'En aras de' significa:", options: ["em prol de", "ao lado de", "contra"], answer: "em prol de", explanation: "Locução formal: en aras de la paz = em prol da paz." },
        { id: "c1-02-q3", type: "fill-blank", question: "nombrar → el ___", answer: "nombramiento", explanation: "NOMBRAR → el nombramiento (sufixo -miento, masculino)." },
        { id: "c1-02-q4", type: "multiple-choice", question: "Gênero dos substantivos em -miento:", options: ["masculino", "feminino", "varia"], answer: "masculino", explanation: "-miento forma sempre substantivos masculinos." },
        { id: "c1-02-q5", type: "multiple-choice", question: "'Dicho esto, pasemos al siguiente punto' contém:", options: ["um participio absoluto", "um gerúndio", "um infinitivo nominal"], answer: "um participio absoluto", explanation: "DICHO ESTO = depois de dizer isto." },
        { id: "c1-02-q6", type: "multiple-choice", question: "'Habida cuenta de los datos' significa:", options: ["levando em conta os dados", "apesar dos dados", "sem os dados"], answer: "levando em conta os dados", explanation: "HABIDA CUENTA DE = considerando." },
        { id: "c1-02-q7", type: "multiple-choice", question: "Infinitivo nominal:", options: ["El saber no ocupa lugar.", "Voy a saber.", "Sabiendo eso…"], answer: "El saber no ocupa lugar.", explanation: "O infinitivo com artigo funciona como substantivo." },
        { id: "c1-02-q8", type: "multiple-choice", question: "Verbo de citação para 'negar uma informação publicada':", options: ["desmentir", "señalar", "apuntar"], answer: "desmentir", explanation: "DESMENTIR = declarar falsa uma informação." },
        { id: "c1-02-q9", type: "multiple-choice", question: "'So pena de multa' pertence ao registro:", options: ["jurídico", "coloquial", "infantil"], answer: "jurídico", explanation: "SO PENA DE = sob pena de, típico de textos legais." },
        { id: "c1-02-q10", type: "multiple-choice", question: "Manchete típica da imprensa espanhola:", options: ["Récord de visitantes en el Prado", "Pues mira, vinieron muchos al Prado", "Yo creo que hubo gente"], answer: "Récord de visitantes en el Prado", explanation: "Nominalização e ausência de verbo, sem marcas de oralidade." },
      ],
