import { EXAM_BANKS } from "./exam-banks";

export const COURSE: CourseLevel[] = [A1, A2, B1, B2, C1, C2];

// Anexa o banco rotativo de questões a cada nível.
COURSE.forEach((c) => {
  c.examBank = EXAM_BANKS[c.level];
});

export const getCourseLevel = (level: LevelId) =>
  COURSE.find((c) => c.level === level);

export const getChapter = (level: LevelId, chapterId: string) =>
  getCourseLevel(level)?.chapters.find((c) => c.id === chapterId);

// Regra de aprovação: 60%.
export const PASS_THRESHOLD = 0.6;

